# Maybe 0s with some threshold of neighbors become 8

def count_0_neighbors(grid, r, c, include_diagonal=False):
    count = 0
    rows, cols = len(grid), len(grid[0])
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0:
                    count += 1
    return count

